import React, { useState, useMemo } from 'react';
import { raceList, horseList, HorseData } from './WbcData'; 
import { Container, Form, Card, Table, Button, Accordion } from 'react-bootstrap'; // ← Accordion を追加
import { useNavigate } from 'react-router-dom';

interface ExtendedHorseData extends HorseData {
  isPlayer?: boolean;
  share?: number;
  adjustedOdds?: number;
}

const WbcRival = () => {
  const navigate = useNavigate();
  const backpage = () => {
    navigate(-1); // ブラウザの戻るボタンと同じ動作になります
  };
  const SIM_PAYOUT = 85.0; 
  const MIN_SHARE = 0.005; 

  // ゲージ用のカラー（画像に合わせて人気順）
  const gaugeColors = ['#5ac8fa', '#ffcc00', '#4cd964', '#ff3b30', '#5856d6', '#ff9500', '#007aff', '#ff2d55', '#d6a2e8', '#8e8e93'];

  const availableYears = useMemo(() => {
    const years = raceList.map(race => race.year);
    return Array.from(new Set(years));
  }, []);

  const [selectedYear, setSelectedYear] = useState(availableYears[0] || '');
  const [selectedRaceName, setSelectedRaceName] = useState('ＷＢＣＩ');
  const [simOdds, setSimOdds] = useState<number | null>(null);

  const racesInSelectedYear = useMemo(() => {
    return raceList.filter(race => race.year === selectedYear);
  }, [selectedYear]);

  const currentRaceInfo = useMemo(() => {
    return racesInSelectedYear.find(r => r.raceName === selectedRaceName);
  }, [racesInSelectedYear, selectedRaceName]);

  const rawHorses = useMemo(() => {
    if (!currentRaceInfo) return [];
    return horseList.filter(horse => horse.raceId === currentRaceInfo.raceId);
  }, [currentRaceInfo]);

  const processedHorses = useMemo((): ExtendedHorseData[] => {
    if (!currentRaceInfo || rawHorses.length === 0) return [];
    if (simOdds === null) return rawHorses.map(h => ({ ...h, isPlayer: false }));

    const sortedRaw = [...rawHorses].sort((a, b) => Number(b.odds) - Number(a.odds));
    const targetHorseName = sortedRaw[0].horseName;

    return rawHorses.map((h): ExtendedHorseData => {
      if (h.horseName === targetHorseName) {
        return { ...h, horseName: "自馬", odds: simOdds, isPlayer: true };
      }
      return { ...h, isPlayer: false };
    });
  }, [rawHorses, simOdds, currentRaceInfo]);

  const { sortedHorses, currentPayout } = useMemo(() => {
    if (processedHorses.length === 0) return { sortedHorses: [], currentPayout: 0 };
    
    const rawWeights = processedHorses.map(h => (1 / Number(h.odds)));
    const rawTotalWeight = rawWeights.reduce((a, b) => a + b, 0);

    let finalWeights: number[];
    let displayPayout: number;

    if (simOdds !== null) {
      displayPayout = SIM_PAYOUT;
      const targetTotalWeight = 1 / (SIM_PAYOUT / 100);
      const myWeight = 1 / simOdds;
      
      finalWeights = [...rawWeights];
      let fixedWeight = 0;
      let flexibleIndices: number[] = [];

      finalWeights.forEach((_, idx) => {
        if (processedHorses[idx].isPlayer) {
          finalWeights[idx] = myWeight;
        } else {
          const minWeight = targetTotalWeight * MIN_SHARE;
          const ratioWeight = (rawWeights[idx] / rawTotalWeight) * (targetTotalWeight - myWeight);
          
          if (ratioWeight < minWeight) {
            finalWeights[idx] = minWeight;
            fixedWeight += minWeight;
          } else {
            flexibleIndices.push(idx);
          }
        }
      });

      const remainingWeight = targetTotalWeight - myWeight - fixedWeight;
      const flexibleWeightSum = flexibleIndices.reduce((sum, idx) => sum + rawWeights[idx], 0);

      flexibleIndices.forEach(idx => {
        finalWeights[idx] = (rawWeights[idx] / flexibleWeightSum) * remainingWeight;
      });

    } else {
      displayPayout = (1 / rawTotalWeight) * 100;
      finalWeights = rawWeights;
    }

    const calculated = processedHorses.map((horse, idx): ExtendedHorseData => {
      const weight = finalWeights[idx];
      const totalW = simOdds !== null ? (1 / (SIM_PAYOUT / 100)) : rawTotalWeight;
      return { 
        ...horse, 
        share: (weight / totalW) * 100, 
        adjustedOdds: 1 / weight 
      };
    });

    return { 
      sortedHorses: calculated.sort((a, b) => (a.adjustedOdds || 0) - (b.adjustedOdds || 0)),
      currentPayout: displayPayout 
    };
  }, [processedHorses, simOdds]);

  return (
    <div style={{ backgroundColor: '#f0f2f5', minHeight: '100vh', paddingBottom: '50px' }}>
      <Container className="pt-4" style={{ maxWidth: '600px' }}>
        
        <Card className="shadow border-0 mb-3" style={{ borderRadius: '16px', overflow: 'hidden' }}>
          <div style={{ height: '6px', backgroundColor: '#3bc0bd' }}></div>
          <Card.Body className="p-4">
            <h4 className="text-center mb-4" style={{ color: '#444', fontWeight: '800' }}>
              WBC VIEWER <span style={{ color: '#3bc0bd', fontSize: '0.8em' }}>| {simOdds ? '自馬参戦中' : '出走馬検索'}</span>
            </h4>

            <div className="mb-4">
              <Form.Label className="small fw-bold text-muted mb-2 text-uppercase d-block">🐎 自馬参戦シミュレーション</Form.Label>
              <div className="d-flex gap-2 align-items-center">
                {[1.3, 4.3].map(odds => (
                  <Button 
                    key={odds}
                    variant={simOdds === odds ? "danger" : "outline-primary"}
                    className="flex-fill fw-bold shadow-sm"
                    style={{ borderRadius: '10px' }}
                    onClick={() => setSimOdds(simOdds === odds ? null : odds)}
                  >
                    {odds.toFixed(1)}倍
                  </Button>
                ))}
                {simOdds !== null && (
                  <Button variant="link" className="text-muted text-decoration-none small fw-bold" onClick={() => setSimOdds(null)}>解除</Button>
                )}
              </div>
            </div>

            <div className="mb-4 p-3" style={{ backgroundColor: '#f8f9fa', borderRadius: '12px' }}>
              <Form.Select value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)} className="border-0 shadow-sm fw-bold">
                {availableYears.map(year => <option key={year} value={year}>{year}</option>)}
              </Form.Select>
            </div>

            <div className="mb-4 d-flex gap-1">
              {racesInSelectedYear.map((race) => (
                <button
                  key={race.raceId}
                  onClick={() => setSelectedRaceName(race.raceName)}
                  style={{
                    flex: 1, border: 'none', borderRadius: '8px', padding: '10px 2px', fontSize: '0.75rem', fontWeight: 'bold',
                    backgroundColor: selectedRaceName === race.raceName ? '#3bc0bd' : '#e9ecef',
                    color: selectedRaceName === race.raceName ? '#fff' : '#666', transition: '0.2s'
                  }}
                >
                  {race.raceName}
                </button>
              ))}
            </div>

            {/* ▼▼▼ ここからアコーディオンに変更 ▼▼▼ */}
            <Accordion className="mb-2 shadow-sm" style={{ borderRadius: '12px', overflow: 'hidden' }}>
              <Accordion.Item eventKey="0" style={{ border: 'none' }}>
                <Accordion.Header>
                  <span style={{ fontSize: '0.85rem', fontWeight: 'bold', color: '#555' }}>📋 レーステーマ・詳細を表示</span>
                </Accordion.Header>
                <Accordion.Body className="p-3" style={{ backgroundColor: '#fff' }}>
                  <div style={{ fontSize: '0.8rem', color: '#555' }}>
                    {racesInSelectedYear.map(race => (
                      <div key={race.raceId} className="d-flex border-bottom py-2 align-items-center" style={{ borderColor: '#f8f9fa', opacity: selectedRaceName === race.raceName ? 1 : 0.4 }}>
                        <div style={{ width: '55px', fontWeight: 'bold', color: '#3bc0bd' }}>{race.raceName}</div>
                        <div style={{ flex: '1', color: '#333', fontWeight: '500' }}>{race.theme}</div>
                        <div className="text-muted text-end" style={{ flex: '1', fontSize: '0.7rem' }}>{race.notes || '-'}</div>
                      </div>
                    ))}
                  </div>
                </Accordion.Body>
              </Accordion.Item>
            </Accordion>
            {/* ▲▲▲ アコーディオン変更ここまで ▲▲▲ */}

          </Card.Body>
        </Card>

        {/* 支持率分布ゲージ */}
        <div className="mb-3 px-1">
          <div className="d-flex align-items-center mb-1">
            <span className="small fw-bold text-muted">📊 支持率分布 (人気順)</span>
          </div>
          <div className="d-flex shadow-sm" style={{ height: '24px', borderRadius: '8px', overflow: 'hidden', backgroundColor: '#e9ecef' }}>
            {sortedHorses.map((horse, idx) => (
              <div
                key={idx}
                style={{
                  width: `${horse.share}%`,
                  backgroundColor: horse.isPlayer ? '#E0115F' : (gaugeColors[idx] || '#999'),
                  transition: 'width 0.4s ease',
                  borderRight: '1px solid rgba(255,255,255,0.2)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', fontSize: '0.65rem', fontWeight: 'bold'
                }}
              >
                {(horse.share || 0) > 8 && (horse.isPlayer ? "★" : idx + 1)}
              </div>
            ))}
          </div>
        </div>

        {/* 【修正】出走表デザインを画像に準拠 */}
        <div className="table-responsive shadow-sm mb-2" style={{ borderRadius: '12px', overflow: 'hidden' }}>
          <Table className="table-bordered mb-0" style={{ fontSize: "15px", verticalAlign: 'middle', border: 'none' }}>
            <thead>
              <tr className="text-white" style={{ border: 'none' }}>
                <th style={{ backgroundColor: simOdds !== null ? '#E0115F' : '#3bc0bd', border: 'none', padding: '12px' }}>出走馬名</th>
                <th className="text-center" style={{ backgroundColor: simOdds !== null ? '#E0115F' : '#3bc0bd', border: 'none', padding: '12px', width: '90px' }}>オッズ</th>
                <th className="text-center" style={{ backgroundColor: simOdds !== null ? '#E0115F' : '#3bc0bd', border: 'none', padding: '12px', width: '90px' }}>支持率</th>
              </tr>
            </thead>
            <tbody>
              {sortedHorses.map((horse, index) => {
                const oddsValue = horse.adjustedOdds || 0;
                const isHighOdds = oddsValue >= 100;
                
                // 背景色と文字色の定義
                const rowBgColor = horse.isPlayer ? '#4b0000' : '#3b3b3b'; 
                const oddsColor = horse.isPlayer ? '#fffa00' : (isHighOdds ? '#00bfff' : '#ffffff');
                const nameColor = horse.isPlayer ? '#fffa00' : '#ffffff';

                return (
                  <tr key={index} style={{ borderBottom: '1px solid #4a4a4a' }}>
                    <td style={{ backgroundColor: rowBgColor, color: nameColor, padding: '12px', textAlign: 'left', fontWeight: 'bold', border: 'none' }}>
                      <div className="d-flex align-items-center">
                        <div className="text-center" style={{ width: '30px', color: horse.isPlayer ? '#fffa00' : '#aaa', fontSize: '0.9em' }}>
                          {horse.isPlayer ? "自馬" : index + 1}
                        </div>
                        <span className="ms-2">{horse.isPlayer ? "🐎" : horse.horseName}</span>
                      </div>
                    </td>
                    <td className="text-center" style={{ 
                        backgroundColor: rowBgColor, color: oddsColor, border: 'none', fontWeight: '900', fontSize: '1.2rem', fontFamily: 'monospace' 
                    }}>
                      {oddsValue.toFixed(1)}
                    </td>
                    <td className="text-center" style={{ 
                        backgroundColor: rowBgColor, color: horse.isPlayer ? '#fffa00' : '#aaa', border: 'none', fontWeight: 'bold', fontFamily: 'monospace' 
                    }}>
                      {(horse.share || 0).toFixed(1)}%
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </Table>
        </div>

        <div className="text-end px-2" style={{ fontSize: '0.75rem', color: '#888', fontWeight: 'bold' }}>
            PAYOUT RATE: <span style={{ color: '#3bc0bd' }}>{currentPayout.toFixed(1)}% {simOdds !== null && "(SIM)"}</span>
        </div>
        <div className="px-1 mt-4">
          <Button variant="success" className="w-100 fw-bold py-2 shadow-sm" style={{ borderRadius: '10px' }} onClick={backpage}>
            戻る
          </Button>
        </div>
      </Container>
    </div>
  );
};

export default WbcRival;