// src/farm/farmApi.ts
// farm-worker（Cloudflare Workers + D1 / starhorse-farm-db）とやり取りするAPIクライアント。

export interface HarvestRecord {
  id: number;
  収穫日時: string;
  厩舎名: string;
  収穫内容: string;
  /** 未記録の行は null。 */
  化粧箱使用: boolean | null;
  登録日時: string;
}

export interface HarvestQuery {
  /** YYYY-MM-DD */
  from?: string;
  /** YYYY-MM-DD */
  to?: string;
  stable?: string;
  q?: string;
  order?: 'asc' | 'desc';
  limit?: number;
}

// qrcode/qrApi.ts と同じ流儀。.env の REACT_APP_FARM_API_BASE でデプロイ済みWorkerを指す。
// 未設定時はローカルの `wrangler dev`（farm-worker は 8788番）を想定。
const API_BASE = process.env.REACT_APP_FARM_API_BASE || 'http://localhost:8788';

async function parseJsonOrThrow(response: Response): Promise<any> {
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(data.error || `HTTP ${response.status}`);
  }
  return data;
}

export async function fetchHarvestRecords(query: HarvestQuery = {}): Promise<HarvestRecord[]> {
  const params = new URLSearchParams();
  if (query.from) params.set('from', query.from);
  if (query.to) params.set('to', query.to);
  if (query.stable) params.set('stable', query.stable);
  if (query.q) params.set('q', query.q);
  if (query.order) params.set('order', query.order);
  if (query.limit) params.set('limit', String(query.limit));

  const suffix = params.toString() ? `?${params.toString()}` : '';
  const res = await fetch(`${API_BASE}/api/harvest${suffix}`);
  return parseJsonOrThrow(res);
}

export async function fetchStableNames(): Promise<string[]> {
  const res = await fetch(`${API_BASE}/api/harvest/stables`);
  return parseJsonOrThrow(res);
}
