import React, { useEffect, useMemo, useState } from 'react';
import { Modal, Spinner, Table, Alert, Badge, Row, Col, Accordion, ToggleButton, ToggleButtonGroup } from 'react-bootstrap';
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, LabelList, PieChart, Pie, Cell,
} from 'recharts';
import { HarvestRecord, fetchHarvestRecords } from './farmApi';
import {
  CATEGORY_COLOR, CATEGORY_ORDER, classifyHarvestContent, COMMENT_COLOR, COMMENT_ORDER,
  computeDorianStats, computePayoutRate, formatHarvestDateTime, harvestItemDetail,
} from './harvestUtils';

/** ペイアウト率のパーセント換算基準（水コメの200点=100%とみなす）。 */
const PAYOUT_PERCENT_BASE = 200;

const RECENT_LIST_COUNT = 10;
const RECENT_STATS_COUNT = 100;
/** 「全データ」トグル時に投げる件数上限（farm-workerのMAX_LIMITに合わせる）。 */
const ALL_DATA_LIMIT = 2000;

type StatsScope = 'recent100' | 'all';

/** 円グラフを出す対象カテゴリ（千両箱・その他はコメントの内訳を出す意味が薄いので除く）。 */
const PIE_CATEGORIES = CATEGORY_ORDER.filter((c) => c !== '千両箱' && c !== 'その他');

interface Props {
  stableName: string | null;
  onHide: () => void;
}

/** 全体を見やすくするための落ち着いた背景色。 */
const MODAL_BODY_BG = '#eef1f0';
const SECTION_BG = '#ffffff';

/** セクションを白いカードで囲み、間隔をそろえるための共通スタイル。 */
const sectionStyle: React.CSSProperties = {
  backgroundColor: SECTION_BG,
  borderRadius: '12px',
  padding: '16px',
  marginBottom: '16px',
  boxShadow: '0 1px 3px rgba(0,0,0,0.06)',
};

/** カテゴリ/コメント共通の色付きバッジ。Bootstrapのbg-*は!importantなのでbg=""で無効化し、hexを直接当てる。 */
const ColorBadge: React.FC<{ bg: string; text: string; className?: string; children: React.ReactNode }> = ({
  bg, text, className, children,
}) => (
  <Badge bg="" className={className} style={{ backgroundColor: bg, color: text }}>
    {children}
  </Badge>
);

/** ある分類（カテゴリ/コメント）の内訳を、指定した並び順の1行データ（100%積み上げ用）にする。 */
function buildBreakdown<T extends string>(
  records: HarvestRecord[],
  pick: (r: HarvestRecord) => T,
  order: readonly T[]
) {
  const counts = new Map<T, number>();
  records.forEach((r) => {
    const key = pick(r);
    counts.set(key, (counts.get(key) || 0) + 1);
  });
  const total = records.length;
  const presentOrder = order.filter((key) => counts.has(key));
  const row: Record<string, number | string> = { name: '構成比' };
  presentOrder.forEach((key) => {
    row[key] = total > 0 ? ((counts.get(key) || 0) / total) * 100 : 0;
  });
  return { row, order: presentOrder, counts, total };
}

/**
 * 厩舎ごとの詳細ポップアップ。
 * 表示中の一覧（画面側のフィルタ）とは無関係に、その厩舎の直近データを
 * 都度APIから取得し直す（「過去10回/過去100回」は常に最新を指すため）。
 */
const StableDetailModal: React.FC<Props> = ({ stableName, onHide }) => {
  const [records, setRecords] = useState<HarvestRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [statsScope, setStatsScope] = useState<StatsScope>('recent100');

  useEffect(() => {
    if (!stableName) return;
    setLoading(true);
    setError(null);
    const limit = statsScope === 'all' ? ALL_DATA_LIMIT : RECENT_STATS_COUNT;
    fetchHarvestRecords({ stable: stableName, order: 'desc', limit })
      .then(setRecords)
      .catch((err: any) => setError(err.message || '取得に失敗しました'))
      .finally(() => setLoading(false));
  }, [stableName, statsScope]);

  // 新しい順で取得しているので、先頭がそのまま直近10回。
  const recent10 = useMemo(() => records.slice(0, RECENT_LIST_COUNT), [records]);

  const categoryBreakdown = useMemo(
    () => buildBreakdown(records, (r) => classifyHarvestContent(r.収穫内容).category, CATEGORY_ORDER),
    [records]
  );

  const commentBreakdown = useMemo(
    () => buildBreakdown(records, (r) => classifyHarvestContent(r.収穫内容).comment, COMMENT_ORDER),
    [records]
  );

  const payout = useMemo(() => computePayoutRate(records), [records]);
  const dorian = useMemo(() => computeDorianStats(records), [records]);

  // カテゴリごとに、そのカテゴリ内でどのコメントが出たかの内訳（円グラフ用）。
  const categoryCommentPies = useMemo(
    () =>
      PIE_CATEGORIES.map((category) => {
        const subset = records.filter((r) => classifyHarvestContent(r.収穫内容).category === category);
        const counts = new Map<string, number>();
        subset.forEach((r) => {
          const { comment } = classifyHarvestContent(r.収穫内容);
          counts.set(comment, (counts.get(comment) || 0) + 1);
        });
        const data = COMMENT_ORDER.filter((c) => counts.has(c)).map((c) => ({ name: c, value: counts.get(c)! }));
        return { category, total: subset.length, data };
      }).filter((p) => p.total > 0),
    [records]
  );

  const scopeLabel = statsScope === 'all' ? '全' : '直近';

  return (
    <Modal show={stableName !== null} onHide={onHide} centered size="lg" scrollable>
      <Modal.Header closeButton style={{ backgroundColor: MODAL_BODY_BG }}>
        <Modal.Title style={{ fontSize: '1.05em' }}>{stableName} の詳細</Modal.Title>
      </Modal.Header>
      <Modal.Body style={{ backgroundColor: MODAL_BODY_BG }}>
        <div className="d-flex justify-content-end mb-3">
          <ToggleButtonGroup
            type="radio"
            name="stats-scope"
            value={statsScope}
            onChange={(v) => setStatsScope(v as StatsScope)}
          >
            <ToggleButton id="scope-recent100" value="recent100" size="sm" variant={statsScope === 'recent100' ? 'dark' : 'outline-dark'}>
              直近100回
            </ToggleButton>
            <ToggleButton id="scope-all" value="all" size="sm" variant={statsScope === 'all' ? 'dark' : 'outline-dark'}>
              全データ
            </ToggleButton>
          </ToggleButtonGroup>
        </div>

        {error && <Alert variant="danger">{error}</Alert>}

        {loading ? (
          <div className="text-center py-5">
            <Spinner animation="border" />
          </div>
        ) : records.length === 0 ? (
          <div className="text-center text-muted py-4">収穫記録がありません</div>
        ) : (
          <>
            {/* 1. ペイアウト率 */}
            <div style={sectionStyle}>
              <div className="d-flex align-items-center flex-wrap gap-3">
                <h6 className="fw-bold mb-0">{scopeLabel}{records.length}回のペイアウト率</h6>
                <div className="px-3 py-1" style={{ backgroundColor: '#f8f9fa', borderRadius: '10px' }}>
                  <span className="fw-bold" style={{ fontSize: '1.4em' }}>
                    {((payout.rate / PAYOUT_PERCENT_BASE) * 100).toFixed(1)}%
                  </span>
                </div>
              </div>
            </div>

            {/* 2. ドリアン統計 */}
            <div style={sectionStyle}>
              <div className="d-flex align-items-center flex-wrap gap-3 mb-2">
                <h6 className="fw-bold mb-0">ドリアン統計（{scopeLabel}{records.length}回）</h6>
                <div>
                  平均取得数: <span className="fw-bold">{dorian.averageCount.toFixed(2)}</span> 個/回
                </div>
              </div>
              <div className="table-responsive">
                <Table size="sm" className="mb-0">
                  <thead>
                    <tr>
                      <th>カテゴリ</th>
                      <th className="text-end">ドリアン収穫数</th>
                      <th className="text-end">発生率</th>
                      <th className="text-end">収穫数</th>
                    </tr>
                  </thead>
                  <tbody>
                    {dorian.byCategory.map((c) => (
                      <tr key={c.category}>
                        <td>
                          <ColorBadge bg={CATEGORY_COLOR[c.category].bg} text={CATEGORY_COLOR[c.category].text}>
                            {c.category}
                          </ColorBadge>
                        </td>
                        <td className="text-end">{c.withDorian}回</td>
                        <td className="text-end fw-bold">{c.rate.toFixed(1)}%</td>
                        <td className="text-end">{c.withDorian}/{c.total}回</td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              </div>
            </div>

            {/* 3. 収穫内容とコメント分布 */}
            <div style={sectionStyle}>
              <h6 className="fw-bold mb-2">
                {scopeLabel}{records.length}回の収穫内容・コメント分布
                {statsScope === 'recent100' && records.length < RECENT_STATS_COUNT && (
                  <span className="text-muted fw-normal small ms-2">
                    （記録が{RECENT_STATS_COUNT}回未満のため全{records.length}回分）
                  </span>
                )}
              </h6>
              <Row className="g-3">
                <Col xs={12} md={6}>
                  <div className="small text-muted mb-1">収穫内容（カテゴリ）別</div>
                  <div style={{ width: '100%', height: 60 }}>
                    <ResponsiveContainer>
                      <BarChart
                        data={[categoryBreakdown.row]}
                        layout="vertical"
                        margin={{ top: 0, right: 8, bottom: 0, left: 0 }}
                      >
                        <XAxis type="number" domain={[0, 100]} hide />
                        <YAxis type="category" dataKey="name" hide />
                        <Tooltip formatter={(value: any) => `${Number(value).toFixed(1)}%`} />
                        {categoryBreakdown.order.map((name) => (
                          <Bar key={name} dataKey={name} stackId="stack" fill={CATEGORY_COLOR[name]?.bg || '#6c757d'}>
                            <LabelList
                              dataKey={name}
                              position="center"
                              formatter={(v: any) => (Number(v) >= 6 ? `${Number(v).toFixed(0)}%` : '')}
                              style={{ fill: '#fff', fontSize: 11, fontWeight: 700 }}
                            />
                          </Bar>
                        ))}
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                  <div className="table-responsive">
                    <Table size="sm" className="mt-2 mb-0">
                      <tbody>
                        {categoryBreakdown.order.map((name) => (
                          <tr key={name}>
                            <td className="py-1">
                              <ColorBadge bg={CATEGORY_COLOR[name]?.bg || '#6c757d'} text={CATEGORY_COLOR[name]?.text || '#fff'}>
                                {name}
                              </ColorBadge>
                            </td>
                            <td className="py-1 text-end">{categoryBreakdown.counts.get(name)}回</td>
                            <td className="py-1 text-end fw-bold" style={{ width: '4.5em' }}>
                              {((categoryBreakdown.counts.get(name)! / categoryBreakdown.total) * 100).toFixed(1)}%
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </Table>
                  </div>
                </Col>
                <Col xs={12} md={6}>
                  <div className="small text-muted mb-1">コメント別</div>
                  <div style={{ width: '100%', height: 60 }}>
                    <ResponsiveContainer>
                      <BarChart
                        data={[commentBreakdown.row]}
                        layout="vertical"
                        margin={{ top: 0, right: 8, bottom: 0, left: 0 }}
                      >
                        <XAxis type="number" domain={[0, 100]} hide />
                        <YAxis type="category" dataKey="name" hide />
                        <Tooltip formatter={(value: any) => `${Number(value).toFixed(1)}%`} />
                        {commentBreakdown.order.map((name) => (
                          <Bar key={name} dataKey={name} stackId="stack" fill={COMMENT_COLOR[name]?.bg || '#6c757d'}>
                            <LabelList
                              dataKey={name}
                              position="center"
                              formatter={(v: any) => (Number(v) >= 6 ? `${Number(v).toFixed(0)}%` : '')}
                              style={{ fill: '#fff', fontSize: 11, fontWeight: 700 }}
                            />
                          </Bar>
                        ))}
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                  <div className="table-responsive">
                    <Table size="sm" className="mt-2 mb-0">
                      <tbody>
                        {commentBreakdown.order.map((name) => (
                          <tr key={name}>
                            <td className="py-1">
                              <ColorBadge bg={COMMENT_COLOR[name].bg} text={COMMENT_COLOR[name].text}>
                                {name}
                              </ColorBadge>
                            </td>
                            <td className="py-1 text-end">{commentBreakdown.counts.get(name)}回</td>
                            <td className="py-1 text-end fw-bold" style={{ width: '4.5em' }}>
                              {((commentBreakdown.counts.get(name)! / commentBreakdown.total) * 100).toFixed(1)}%
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </Table>
                  </div>
                </Col>
              </Row>

              <Accordion className="mt-3">
                <Accordion.Item eventKey="pies">
                  <Accordion.Header>収穫内容ごとのコメント割合</Accordion.Header>
                  <Accordion.Body>
                    <Row className="g-3">
                      {categoryCommentPies.map(({ category, total, data }) => (
                        <Col xs={6} md={4} key={category} className="text-center">
                          <ColorBadge bg={CATEGORY_COLOR[category].bg} text={CATEGORY_COLOR[category].text} className="mb-1">
                            {category}
                          </ColorBadge>
                          <div style={{ width: '100%', height: 130 }}>
                            <ResponsiveContainer>
                              <PieChart>
                                <Tooltip
                                  itemStyle={{ color: '#000' }}
                                  labelStyle={{ color: '#000' }}
                                  contentStyle={{ backgroundColor: '#fff', border: '1px solid #ddd' }}
                                  formatter={(value: any, name: any) => [
                                    `${value}回 (${((Number(value) / total) * 100).toFixed(1)}%)`,
                                    name,
                                  ]}
                                />
                                <Pie
                                  data={data}
                                  dataKey="value"
                                  nameKey="name"
                                  innerRadius={20}
                                  outerRadius={45}
                                  startAngle={90}
                                  endAngle={-270}
                                >
                                  {data.map((entry) => (
                                    <Cell key={entry.name} fill={COMMENT_COLOR[entry.name as keyof typeof COMMENT_COLOR]?.bg || '#6c757d'} />
                                  ))}
                                </Pie>
                              </PieChart>
                            </ResponsiveContainer>
                          </div>
                          <div className="text-muted small">全{total}回</div>
                        </Col>
                      ))}
                    </Row>
                  </Accordion.Body>
                </Accordion.Item>
              </Accordion>
            </div>

            {/* 4. 直近10回内容 */}
            <div style={sectionStyle}>
              <h6 className="fw-bold mb-2">直近{RECENT_LIST_COUNT}回の収穫内容</h6>
              <div className="table-responsive">
                <Table size="sm" hover className="mb-0">
                  <thead>
                    <tr>
                      <th style={{ whiteSpace: 'nowrap' }}>収穫日時</th>
                      <th>収穫内容</th>
                      <th style={{ whiteSpace: 'nowrap' }}>コメント</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recent10.map((r) => {
                      const { category, comment } = classifyHarvestContent(r.収穫内容);
                      const itemDetail = harvestItemDetail(r.収穫内容, category);
                      return (
                        <tr key={r.id}>
                          <td style={{ whiteSpace: 'nowrap' }}>{formatHarvestDateTime(r.収穫日時)}</td>
                          <td style={{ whiteSpace: 'nowrap' }}>
                            <ColorBadge className="me-2" bg={CATEGORY_COLOR[category].bg} text={CATEGORY_COLOR[category].text}>
                              {category}
                            </ColorBadge>
                            {itemDetail && <span className="text-muted small">{itemDetail}</span>}
                          </td>
                          <td style={{ whiteSpace: 'nowrap' }}>
                            <ColorBadge bg={COMMENT_COLOR[comment].bg} text={COMMENT_COLOR[comment].text}>
                              {comment}
                            </ColorBadge>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </Table>
              </div>
            </div>
          </>
        )}
      </Modal.Body>
    </Modal>
  );
};

export default StableDetailModal;
