import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Container, Row, Col, Card, Table, Form, Button, Spinner, Alert, ButtonGroup,
} from 'react-bootstrap';
import { HarvestRecord, fetchHarvestRecords, fetchStableNames } from './farmApi';
import {
  CATEGORY_COLOR, CATEGORY_ORDER, classifyHarvestContent, COMMENT_COLOR, COMMENT_ORDER,
  formatHarvestDateTime,
} from './harvestUtils';
import StableDetailModal from './StableDetailModal';

// 一覧のトップ画面（フィルタなしの初期表示）では直近20件だけを見せる。
const DEFAULT_DISPLAY_LIMIT = 20;

const HEADER_GRADIENT = 'linear-gradient(135deg, #00695c 0%, #004d40 100%)';
// 注意: Bootstrapの.tableは td/th 自身に background-color を直接当てる(tr の背景では上書きされない)ため、
// 背景は必ずセル(th/td)側のstyleに指定すること。
const theadThStyle: React.CSSProperties = {
  background: HEADER_GRADIENT,
  color: '#fff',
  fontWeight: 700,
  fontSize: '11px',
  letterSpacing: '0.04em',
  textTransform: 'uppercase',
  padding: '12px 14px',
  border: 'none',
  whiteSpace: 'nowrap',
  cursor: 'pointer',
  userSelect: 'none',
};

type SortKey = 'date' | 'stable' | 'category' | 'comment' | 'box';

const CATEGORY_RANK = new Map(CATEGORY_ORDER.map((c, i) => [c, i]));
const COMMENT_RANK = new Map(COMMENT_ORDER.map((c, i) => [c, i]));
const boxRank = (v: boolean | null) => (v === null ? -1 : v ? 1 : 0);

/**
 * 牧場の収穫履歴（いつ・だれが・なにを取得したか）の確認ページ。
 * データは Cloudflare D1（starhorse-farm-db / harvest_log）を farm-worker 経由で読む。
 * 一覧メニューには載せず /#/harvest で直接開く。
 */
const HarvestLog: React.FC = () => {
  const [records, setRecords] = useState<HarvestRecord[]>([]);
  const [stables, setStables] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);

  // 絞り込み条件（変更したらそのままAPIへ渡す）
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [stable, setStable] = useState('');
  const [keyword, setKeyword] = useState('');
  const [order, setOrder] = useState<'desc' | 'asc'>('desc');
  const [showSummary, setShowSummary] = useState(true);
  const [detailStable, setDetailStable] = useState<string | null>(null);
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'asc' | 'desc' } | null>(null);

  useEffect(() => {
    document.title = '収穫履歴';
  }, []);

  const load = useCallback(() => {
    setLoading(true);
    setLoadError(null);
    fetchHarvestRecords({ from, to, stable, q: keyword, order, limit: DEFAULT_DISPLAY_LIMIT })
      .then(setRecords)
      .catch((err: any) => setLoadError(err.message || '収穫履歴の取得に失敗しました'))
      .finally(() => setLoading(false));
  }, [from, to, stable, keyword, order]);

  useEffect(() => {
    load();
  }, [load]);

  // 厩舎名のプルダウンは全件から作るので初回のみ取得する。
  useEffect(() => {
    fetchStableNames()
      .then(setStables)
      .catch(() => setStables([]));
  }, []);

  const sortedRecords = useMemo(() => {
    if (!sortConfig) return records;
    const dir = sortConfig.direction === 'asc' ? 1 : -1;
    const withMeta = records.map((r) => ({ r, c: classifyHarvestContent(r.収穫内容) }));
    withMeta.sort((a, b) => {
      switch (sortConfig.key) {
        case 'date':
          return a.r.収穫日時.localeCompare(b.r.収穫日時) * dir;
        case 'stable':
          return (a.r.厩舎名 || '').localeCompare(b.r.厩舎名 || '', 'ja') * dir;
        case 'category':
          return ((CATEGORY_RANK.get(a.c.category) ?? 999) - (CATEGORY_RANK.get(b.c.category) ?? 999)) * dir;
        case 'comment':
          return ((COMMENT_RANK.get(a.c.comment) ?? 999) - (COMMENT_RANK.get(b.c.comment) ?? 999)) * dir;
        case 'box':
          return (boxRank(a.r.化粧箱使用) - boxRank(b.r.化粧箱使用)) * dir;
        default:
          return 0;
      }
    });
    return withMeta.map((x) => x.r);
  }, [records, sortConfig]);

  const handleSort = (key: SortKey) => {
    setSortConfig((prev) =>
      prev && prev.key === key
        ? { key, direction: prev.direction === 'asc' ? 'desc' : 'asc' }
        : { key, direction: 'asc' }
    );
  };

  const sortArrow = (key: SortKey) =>
    !sortConfig || sortConfig.key !== key ? '' : sortConfig.direction === 'asc' ? ' ▲' : ' ▼';

  const handleReset = () => {
    setFrom('');
    setTo('');
    setStable('');
    setKeyword('');
    setOrder('desc');
  };

  return (
    <Container className="py-4">
      <div className="mb-4">
        <h2 className="fw-bold mb-1">収穫履歴</h2>
        <p className="text-muted mb-0">いつ・どの厩舎が・なにを収穫したかの記録</p>
      </div>

      {/* ---------- 絞り込み ---------- */}
      <Card className="shadow-sm border-0 mb-4">
        <Card.Body>
          <Row className="g-2 g-md-3 align-items-end">
            <Col xs={6} md={3}>
              <Form.Label className="small text-muted mb-1">開始日</Form.Label>
              <Form.Control
                type="date"
                value={from}
                onChange={(e) => setFrom(e.target.value)}
              />
            </Col>
            <Col xs={6} md={3}>
              <Form.Label className="small text-muted mb-1">終了日</Form.Label>
              <Form.Control
                type="date"
                value={to}
                onChange={(e) => setTo(e.target.value)}
              />
            </Col>
            <Col xs={6} md={3}>
              <Form.Label className="small text-muted mb-1">厩舎</Form.Label>
              <Form.Select value={stable} onChange={(e) => setStable(e.target.value)}>
                <option value="">すべて</option>
                {stables.map((name) => (
                  <option key={name} value={name}>{name}</option>
                ))}
              </Form.Select>
            </Col>
            <Col xs={6} md={3}>
              <Form.Label className="small text-muted mb-1">キーワード</Form.Label>
              <Form.Control
                type="search"
                placeholder="収穫内容・厩舎名"
                value={keyword}
                onChange={(e) => setKeyword(e.target.value)}
              />
            </Col>
          </Row>

          <div className="d-flex flex-wrap gap-2 mt-3">
            <ButtonGroup size="sm">
              <Button
                variant={order === 'desc' ? 'dark' : 'outline-dark'}
                onClick={() => setOrder('desc')}
              >
                新しい順
              </Button>
              <Button
                variant={order === 'asc' ? 'dark' : 'outline-dark'}
                onClick={() => setOrder('asc')}
              >
                古い順
              </Button>
            </ButtonGroup>
            <Button size="sm" variant="outline-secondary" onClick={handleReset}>
              条件クリア
            </Button>
            <Button size="sm" variant="outline-primary" onClick={load} disabled={loading}>
              再読み込み
            </Button>
            <Button
              size="sm"
              variant="outline-secondary"
              onClick={() => setShowSummary((prev) => !prev)}
            >
              {showSummary ? '集計を隠す' : '集計を表示'}
            </Button>
            <span className="ms-auto align-self-center text-muted small">
              {loading ? '読み込み中…' : `${records.length}件`}
            </span>
          </div>
        </Card.Body>
      </Card>

      {loadError && (
        <Alert variant="danger">
          {loadError}
          <div className="small mt-1">
            farm-worker が動いているか、.env の REACT_APP_FARM_API_BASE を確認してください。
          </div>
        </Alert>
      )}

      {/* ---------- 集計 ---------- */}
      {/* 厩舎別の詳細は一覧の表示件数制限とは無関係に、収穫実績があるユーザ全員を出す。 */}
      {showSummary && !loading && stables.length > 0 && (
        <Row className="g-3 mb-4">
          <Col md={12}>
            <Card className="shadow-sm border-0 h-100">
              <Card.Body>
                <Card.Title className="fw-bold h6">厩舎別の詳細</Card.Title>
                <div className="d-flex flex-wrap gap-2 mt-2">
                  {stables.map((name) => (
                    <div
                      key={name}
                      className="d-flex align-items-center gap-2 border rounded p-2"
                    >
                      <span>{name}</span>
                      <Button
                        size="sm"
                        variant="outline-dark"
                        onClick={() => setDetailStable(name)}
                      >
                        詳細
                      </Button>
                    </div>
                  ))}
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}

      {/* ---------- 一覧 ---------- */}
      <Card className="shadow-sm border-0">
        <Card.Body className="p-0">
          {loading ? (
            <div className="text-center py-5">
              <Spinner animation="border" />
            </div>
          ) : records.length === 0 ? (
            <div className="text-center text-muted py-5">該当する収穫記録がありません</div>
          ) : (
            <div className="table-responsive">
              <Table hover className="mb-0 align-middle" style={{ fontSize: '13px' }}>
                <thead>
                  <tr>
                    <th style={theadThStyle} onClick={() => handleSort('date')}>収穫日時{sortArrow('date')}</th>
                    <th style={theadThStyle} onClick={() => handleSort('stable')}>厩舎名{sortArrow('stable')}</th>
                    <th style={theadThStyle} onClick={() => handleSort('category')}>収穫内容{sortArrow('category')}</th>
                    <th style={theadThStyle} onClick={() => handleSort('comment')}>コメント{sortArrow('comment')}</th>
                    <th style={{ ...theadThStyle, textAlign: 'center' }} onClick={() => handleSort('box')}>
                      化粧箱{sortArrow('box')}
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {sortedRecords.map((record, idx) => {
                    const { comment, category } = classifyHarvestContent(record.収穫内容);
                    const accent = CATEGORY_COLOR[category]?.bg || '#6c757d';
                    const rowBg = idx % 2 === 0 ? '#ffffff' : '#f7f9fa';
                    return (
                      <tr key={record.id}>
                        <td
                          style={{
                            whiteSpace: 'nowrap',
                            padding: '10px 14px',
                            backgroundColor: rowBg,
                            borderLeft: `4px solid ${accent}`,
                          }}
                        >
                          {formatHarvestDateTime(record.収穫日時)}
                        </td>
                        <td style={{ whiteSpace: 'nowrap', padding: '10px 14px', backgroundColor: rowBg }}>
                          {record.厩舎名 || '—'}
                        </td>
                        <td
                          style={{
                            whiteSpace: 'nowrap', padding: '10px 14px', backgroundColor: rowBg,
                            color: accent, fontWeight: 700,
                          }}
                        >
                          {category}
                        </td>
                        <td
                          style={{
                            whiteSpace: 'nowrap',
                            padding: '10px 14px',
                            backgroundColor: rowBg,
                            color: COMMENT_COLOR[comment]?.bg || '#6c757d',
                            fontWeight: 700,
                          }}
                        >
                          {comment}
                        </td>
                        <td
                          className="text-center"
                          style={{
                            padding: '10px 14px',
                            backgroundColor: rowBg,
                            color: record.化粧箱使用 ? '#198754' : '#6c757d',
                            fontWeight: record.化粧箱使用 ? 700 : 400,
                          }}
                        >
                          {record.化粧箱使用 === null
                            ? '—'
                            : record.化粧箱使用 ? '使用' : 'なし'}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </Table>
            </div>
          )}
        </Card.Body>
      </Card>

      <StableDetailModal stableName={detailStable} onHide={() => setDetailStable(null)} />
    </Container>
  );
};

export default HarvestLog;
